import { type SynapseEnhancedHttpClient } from "../utils/http.ts";
import { ErrorCode } from "../utils/error-codes.ts";
import { mapParams, sanitizeLimit } from "../utils/api-mapping.ts";
import { MatrixClientApi, SynapseAdminApi } from "../constants/api.ts";
import { handleApiResponse } from "../utils/response-formatter.ts";
import { BaseApi } from "../utils/base-api.ts";
import { InputValidator } from "../utils/validator.ts";

// Maximum query length to prevent DoS attacks
const MAX_QUERY_LENGTH = 500;
// Minimum query length to prevent empty searches
const MIN_QUERY_LENGTH = 1;

export interface IMessageSearchResult {
    message_id: string;
    room_id: string;
    sender_id: string;
    content: string;
    message_type: string;
    timestamp: string;
    relevance_score?: number;
}

export interface IMessageSearchParams {
    user_id: string;
    query: string;
    limit?: number;
    room_id?: string;
}

export interface IPaginationResult<T> {
    items: T[];
    pagination: {
        page: number;
        limit: number;
        total: number;
        has_more: boolean;
    };
}

export class MessagesApi extends BaseApi {
    public constructor(httpClient: SynapseEnhancedHttpClient) {
        super(httpClient);
    }

    /**
     * Sanitize search query to prevent injection attacks
     * @param query - The raw search query
     * @returns Sanitized query string
     */
    private sanitizeSearchQuery(query: string): string {
        if (!query || typeof query !== "string") {
            throw this.createError("query is required and must be a string", ErrorCode.INVALID_PARAM);
        }

        // Trim and check length
        query = query.trim();
        if (query.length < MIN_QUERY_LENGTH || query.length > MAX_QUERY_LENGTH) {
            throw this.createError(
                `query length must be between ${MIN_QUERY_LENGTH} and ${MAX_QUERY_LENGTH} characters`,
                ErrorCode.INVALID_PARAM,
            );
        }

        // Sanitize to remove potentially dangerous characters
        query = InputValidator.sanitizeString(query, MAX_QUERY_LENGTH);

        // Additional check for SQL injection patterns
        if (InputValidator.checkForSqlInjection(query)) {
            throw this.createError("query contains potentially dangerous patterns", ErrorCode.INVALID_PARAM);
        }

        return query;
    }

    /**
     * Search messages for a user
     */
    public async searchMessages(params: IMessageSearchParams): Promise<IMessageSearchResult[]> {
        if (!params.user_id || typeof params.user_id !== "string" || params.user_id.trim().length === 0) {
            throw this.createError("user_id is required and must be a non-empty string", ErrorCode.INVALID_PARAM);
        }

        // Sanitize query to prevent injection attacks
        const sanitizedQuery = this.sanitizeSearchQuery(params.query);

        if (
            params.limit !== undefined &&
            (typeof params.limit !== "number" || params.limit < 1 || params.limit > 100)
        ) {
            throw this.createError("limit must be a number between 1 and 100", ErrorCode.INVALID_PARAM);
        }

        const mappedParams = mapParams(
            {
                user_id: params.user_id,
                query: sanitizedQuery,
                limit: params.limit || 50,
                room_id: params.room_id,
            },
            "messages",
        );

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                results?: IMessageSearchResult[];
            };
            error?: string;
        }>(MatrixClientApi.MESSAGES_SEARCH, mappedParams);

        const data = handleApiResponse(response, "Failed to search messages");
        return data.results || [];
    }

    /**
     * Search messages with pagination
     */
    public async searchMessagesWithPagination(
        params: IMessageSearchParams & { page?: number; limit?: number },
    ): Promise<IPaginationResult<IMessageSearchResult>> {
        if (!params.user_id || typeof params.user_id !== "string" || params.user_id.trim().length === 0) {
            throw this.createError("user_id is required and must be a non-empty string", ErrorCode.INVALID_PARAM);
        }

        // Sanitize query to prevent injection attacks
        const sanitizedQuery = this.sanitizeSearchQuery(params.query);

        const page = params.page || 1;
        const limit = sanitizeLimit(params.limit) || 20;
        const offset = (page - 1) * limit;

        if (page < 1) {
            throw this.createError("page must be a positive number", ErrorCode.INVALID_PARAM);
        }

        if (limit < 1 || limit > 100) {
            throw this.createError("limit must be a number between 1 and 100", ErrorCode.INVALID_PARAM);
        }

        const mappedParams = mapParams(
            {
                user_id: params.user_id,
                query: sanitizedQuery,
                limit: limit,
                offset: offset,
                room_id: params.room_id,
            },
            "messages",
        );

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                results?: IMessageSearchResult[];
                total?: number;
            };
            error?: string;
        }>(MatrixClientApi.MESSAGES_SEARCH, mappedParams);

        const data = handleApiResponse(response, "Failed to search messages");

        const results = data.results || [];
        const total = data.total || results.length;

        return {
            items: results,
            pagination: {
                page: page,
                limit: limit,
                total: total,
                has_more: offset + results.length < total,
            },
        };
    }

    /**
     * Search messages in a specific room
     */
    public async searchMessagesInRoom(
        roomId: string,
        userId: string,
        query: string,
        limit?: number,
    ): Promise<IMessageSearchResult[]> {
        // Sanitize query to prevent injection attacks
        const sanitizedQuery = this.sanitizeSearchQuery(query);

        const mappedParams = mapParams(
            {
                user_id: userId,
                query: sanitizedQuery,
                limit: limit || 50,
            },
            "messages",
        );
        const endpoint = SynapseAdminApi.ROOMS_MESSAGES.replace("{roomId}", encodeURIComponent(roomId));
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                results?: IMessageSearchResult[];
            };
            error?: string;
        }>(endpoint, mappedParams);

        const data = handleApiResponse(response, "Failed to search messages in room");
        return data.results || [];
    }

    /**
     * Get recent messages for a user
     */
    public async getRecentMessages(userId: string, limit: number = 50): Promise<IMessageSearchResult[]> {
        const mappedParams = mapParams(
            {
                user_id: userId,
                limit: limit,
            },
            "messages",
        );
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                results?: IMessageSearchResult[];
            };
            error?: string;
        }>(MatrixClientApi.MESSAGES_SEARCH + "/recent", mappedParams);

        const data = handleApiResponse(response, "Failed to get recent messages");
        return data.results || [];
    }
}
